mapper.select:
SELECT
,zhaopin.zhaopin_gangwei_name as zhaopinGangweiName ,zhaopin.zhaopin_leixing as zhaopinLeixing ,zhaopin.xinzi_fanwei as xinziFanwei ,zhaopin.gongzuo_dizhi as gongzuoDizhi ,zhaopin.gongzuo_yaoqiu as gongzuoYaoqiu ,zhaopin.yizhao_renshu as yizhaoRenshu ,zhaopin.zhaopin_renshu as zhaopinRenshu ,qiye.qiye_name as qiyeName ,qiye.qiye_bianhao as qiyeBianhao ,qiye.qiye_address as qiyeAddress ,qiye.qiye_phone as qiyePhone ,qiye.qiye_email as qiyeEmail ,qiye.qiye_types as qiyeTypes ,xuesheng.xuesheng_name as xueshengName ,xuesheng.xuesheng_xuehao as xueshengXuehao ,xuesheng.xuesheng_phone as xueshengPhone ,xuesheng.xuesheng_id_number as xueshengIdNumber ,xuesheng.xuesheng_photo as xueshengPhoto ,xuesheng.xuesheng_jianli_file as xueshengJianliFile ,xuesheng.yuanxi_types as yuanxiTypes ,xuesheng.zhuanye_types as zhuanyeTypes ,xuesheng.banji_types as banjiTypes ,xuesheng.ruxue_year as ruxueYear ,xuesheng.xuesheng_email as xueshengEmail FROM yingpin a left JOIN zhaopin_gangwei zhaopin ON a.zhaopin_id = zhaopin.id left JOIN qiye qiye ON a.qiye_id = qiye.id left JOIN xuesheng xuesheng ON a.xuesheng_id = xuesheng.id
and a.id in
#{item}
and a.zhaopin_id = #{params.zhaopinId}
and a.xuesheng_id = #{params.xueshengId}
and a.qiye_id = #{params.qiyeId}
and a.yingpin_status like CONCAT('%',#{params.yingpinStatus},'%')
and zhaopin.zhaopin_gangwei_name like CONCAT('%',#{params.zhaopinGangweiName},'%')
and zhaopin.zhaopin_leixing like CONCAT('%',#{params.zhaopinLeixing},'%')
and qiye.qiye_name like CONCAT('%',#{params.qiyeName},'%')
and xuesheng.xuesheng_name like CONCAT('%',#{params.xueshengName},'%')
and xuesheng.xuesheng_xuehao like CONCAT('%',#{params.xueshengXuehao},'%')
and xuesheng.yuanxi_types = #{params.yuanxiTypes}
and xuesheng.zhuanye_types = #{params.zhuanyeTypes}
and xuesheng.banji_types = #{params.banjiTypes}
order by a.${params.orderBy} desc
